<?php $editing = is_array($lead); $value = fn(string $key, mixed $fallback='') => old($key, $editing ? ($lead[$key] ?? $fallback) : $fallback); ?>
<div class="page-heading"><div><a class="back-link" href="<?= e($editing ? url('leads/'.$lead['id']) : url('leads')) ?>"><i class="bi bi-arrow-left"></i> Back to leads</a><h1><?= $editing ? 'Edit lead' : 'Create a lead' ?></h1><p>Keep the essential details clear and actionable.</p></div></div>
<form class="panel form-panel" method="post" action="<?= e($editing ? url('leads/'.$lead['id'].'/edit') : url('leads')) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-section"><span class="section-number">01</span><div><h2>Contact details</h2><p>Who is the opportunity and how can your team reach them?</p></div></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Lead name *</label><input class="form-control <?= validation_error('name')?'is-invalid':'' ?>" name="name" value="<?= e((string)$value('name')) ?>" required maxlength="150"><?php if($error=validation_error('name')):?><div class="invalid-feedback"><?=e($error)?></div><?php endif;?></div><div class="col-md-6"><label class="form-label">Company / business</label><input class="form-control" name="company_name" value="<?= e((string)$value('company_name')) ?>" maxlength="200"></div><div class="col-md-6"><label class="form-label">Phone *</label><input class="form-control <?= validation_error('phone')?'is-invalid':'' ?>" name="phone" value="<?= e((string)$value('phone')) ?>" required maxlength="30"><?php if($error=validation_error('phone')):?><div class="invalid-feedback"><?=e($error)?></div><?php endif;?></div><div class="col-md-6"><label class="form-label">Email</label><input type="email" class="form-control <?= validation_error('email')?'is-invalid':'' ?>" name="email" value="<?= e((string)$value('email')) ?>" maxlength="255"><?php if($error=validation_error('email')):?><div class="invalid-feedback"><?=e($error)?></div><?php endif;?></div><div class="col-md-6"><label class="form-label">City</label><input class="form-control" name="city" value="<?= e((string)$value('city')) ?>" maxlength="100"></div><div class="col-md-6"><label class="form-label">Lead source</label><select class="form-select" name="lead_source"><option value="">Select source</option><?php foreach($sources as $source):?><option value="<?=e($source)?>" <?=$value('lead_source')===$source?'selected':''?>><?=e(ucwords(strtolower(str_replace('_',' ',$source))))?></option><?php endforeach;?></select></div></div>
<hr><div class="form-section"><span class="section-number">02</span><div><h2>Sales plan</h2><p>Set ownership, value, stage and the next action.</p></div></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Stage *</label><select class="form-select" name="stage" required><?php foreach($stages as $stage):?><option value="<?=e($stage)?>" <?=$value('stage','NEW')===$stage?'selected':''?>><?=e(ucfirst(strtolower($stage)))?></option><?php endforeach;?></select></div><?php if($user['role']==='OWNER'):?><div class="col-md-6"><label class="form-label">Assigned BDE</label><select class="form-select <?=validation_error('assigned_to')?'is-invalid':''?>" name="assigned_to"><option value="">Unassigned</option><?php foreach($bdes as $bde):?><option value="<?=(int)$bde['id']?>" <?=(int)$value('assigned_to')===(int)$bde['id']?'selected':''?>><?=e($bde['name'])?></option><?php endforeach;?></select><?php if($error=validation_error('assigned_to')):?><div class="invalid-feedback"><?=e($error)?></div><?php endif;?></div><?php endif;?><div class="col-md-6"><label class="form-label">Estimated value (₹)</label><input type="number" min="0" step="0.01" class="form-control <?=validation_error('estimated_value')?'is-invalid':''?>" name="estimated_value" value="<?=e((string)$value('estimated_value'))?>"><?php if($error=validation_error('estimated_value')):?><div class="invalid-feedback"><?=e($error)?></div><?php endif;?></div><div class="col-md-6"><label class="form-label">Next follow-up</label><input type="datetime-local" class="form-control" name="next_follow_up" value="<?=e($value('next_follow_up')?date('Y-m-d\TH:i',strtotime((string)$value('next_follow_up'))):'')?>"></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="3" maxlength="5000"><?=e((string)$value('notes'))?></textarea></div><div class="col-12 lost-reason-wrap <?= $value('stage','NEW')==='LOST'?'':'d-none' ?>"><label class="form-label">Lost reason</label><textarea class="form-control" name="lost_reason" rows="2" maxlength="2000"><?=e((string)$value('lost_reason'))?></textarea></div></div><div class="form-actions"><a class="btn btn-light" href="<?=e(url('leads'))?>">Cancel</a><button class="btn btn-primary"><i class="bi bi-check2"></i> <?= $editing?'Save changes':'Create lead' ?></button></div></form>
